/*
 * Test and demonstration of BN_hex2bn() and BN_dec2bn().
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/bn.h>
#include <openssl/err.h>
#include "fuzzer.h"

int FuzzerInitialize(int *argc, char ***argv)
{
    OPENSSL_init_crypto(OPENSSL_INIT_LOAD_CRYPTO_STRINGS, NULL);
    ERR_clear_error();
    return 1;
}

int FuzzerTestOneInput(const uint8_t *buf, size_t len)
{
    int success = 0;
    BIGNUM *bn = NULL;
    char *s = (char *)buf;
    char *s2 = NULL;

    if (len == 0)
        return 0;

    if (buf[len - 1] == 0) {
        /* If the last byte is zero, try BN_dec2bn */
        success = BN_dec2bn(&bn, s);
    } else {
        /* Otherwise try BN_hex2bn */
        success = BN_hex2bn(&bn, s);
    }

    if (success) {
        s2 = BN_bn2dec(bn);
        if (s2 != NULL) {
            BN_dec2bn(&bn, s2);
            OPENSSL_free(s2);
        }
        s2 = BN_bn2hex(bn);
        if (s2 != NULL) {
            BN_hex2bn(&bn, s2);
            OPENSSL_free(s2);
        }
    }

    BN_free(bn);
    return 0;
}
